 IntPtr NativeKeyboardTarget(){uint pid;uint thread=GetWindowThreadProcessId(Handle,out pid);var info=new GUIINFO{size=Marshal.SizeOf(typeof(GUIINFO))};if(!GetGUIThreadInfo(thread,ref info)||info.focus==IntPtr.Zero||!IsChild(Handle,info.focus))throw new Exception("Embedded native keyboard focus is missing");return info.focus;}
